From 465a424c91c38f4b2ddb68cfe66b34a001f5b985 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 29 Oct 2026 15:08:31 +0100
Subject: [PATCH] applets/appmenu: Don't crash when search results are deleted

The search kept raw pointers to the actions it listed as results, so when
the app rebuilt one of its submenus the next change of the search text
removed the deleted actions again and crashed. Hold them as QPointer.

BUG: 526561
---
 applets/appmenu/appmenumodel.cpp | 9 ++++++---
 applets/appmenu/appmenumodel.h   | 2 +-
 2 files changed, 7 insertions(+), 4 deletions(-)

diff --git a/applets/appmenu/appmenumodel.cpp b/applets/appmenu/appmenumodel.cpp
index e91d858062..31916fec09 100644
--- a/applets/appmenu/appmenumodel.cpp
+++ b/applets/appmenu/appmenumodel.cpp
@@ -101,8 +101,11 @@ AppMenuModel::AppMenuModel(QObject *parent)
             insertSearchActionsIntoMenu(m_searchBar->text());
         });
         connect(m_searchBar, &QLineEdit::returnPressed, this, [this]() mutable {
-            if (!m_currentSearchActions.empty()) {
-                m_currentSearchActions.constFirst()->trigger();
+            for (const auto &action : std::as_const(m_currentSearchActions)) {
+                if (action) {
+                    action->trigger();
+                    break;
+                }
             }
         });
         connect(this, &AppMenuModel::modelNeedsUpdate, m_searchBar, [this]() mutable {
@@ -186,7 +189,7 @@ void AppMenuModel::removeSearchActionsFromMenu()
     for (auto action : std::as_const(m_currentSearchActions)) {
         m_searchAction->menu()->removeAction(action);
     }
-    m_currentSearchActions = QList<QAction *>();
+    m_currentSearchActions.clear();
 }

 void AppMenuModel::insertSearchActionsIntoMenu(const QString &filter)
diff --git a/applets/appmenu/appmenumodel.h b/applets/appmenu/appmenumodel.h
index ba4a64eaa1..8cef2fccb9 100644
--- a/applets/appmenu/appmenumodel.h
+++ b/applets/appmenu/appmenumodel.h
@@ -95,7 +95,7 @@ private:
     QPointer<QMenu> m_menu;
     QPointer<QAction> m_searchAction;
     QPointer<QLineEdit> m_searchBar;
-    QList<QAction *> m_currentSearchActions;
+    QList<QPointer<QAction>> m_currentSearchActions;

     void removeSearchActionsFromMenu();
     void insertSearchActionsIntoMenu(const QString &filter = QString());
